\begin{definition}[Ramp]
\label{def:ramp-curve}
A curve in $M\times S^1_\lambda$ is a \emph{ramp} if
$u=\langle S,U\rangle>0$ everywhere.
\end{definition}

\begin{corollary}[Ramps remain ramps under curve-shrinking flow]

